package com.medicine.reminder.controller; import com.medicine.reminder.dto.*; import com.medicine.reminder.model.*; import com.medicine.reminder.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/reminders") public class ReminderController {private final ReminderService s;public ReminderController(ReminderService x){s=x;}private Long u(Authentication a){return(Long)a.getDetails();}@GetMapping public List<Reminder> list(@RequestParam Long medicineId,Authentication a){return s.list(medicineId,u(a));}@PostMapping public Reminder create(@Valid @RequestBody ReminderDTO d,Authentication a){return s.create(d,u(a));}@PutMapping("/{id}") public Reminder update(@PathVariable Long id,@Valid @RequestBody ReminderDTO d,Authentication a){return s.update(id,d,u(a));}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id,Authentication a){s.delete(id,u(a));}}
